    input clk, load, clear;
    input [9:0] data;
    output reg [4:0] count;

    // Internal variable to accumulate the number of transitions
    reg [4:0] transitions;

    always @(posedge clk or negedge clear) begin
        if (!clear) begin
            // Asynchronous clear - reset the count and transitions variables
            count <= 5'b0;
            transitions <= 5'b0;
        end else if (load) begin
